async function pobierzPostBezpiecznie(id) {
  const odpowiedz = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`);

  if (!odpowiedz.ok) {
    throw new Error(`HTTP ${odpowiedz.status}: ${odpowiedz.statusText}`);
  }

  return odpowiedz.json();
}

pobierzPostBezpiecznie(99999).catch((err) => console.log(err.message));
// -> "HTTP 404: Not Found"

async function wczytajPosty() {
  try {
    const odpowiedz = await fetch("https://jsonplaceholder.typicode.com/posts?_limit=5");

    if (!odpowiedz.ok) {
      throw new Error(`HTTP ${odpowiedz.status}: ${odpowiedz.statusText}`);
    }

    const posty = await odpowiedz.json();
    console.log(`Zaladowano ${posty.length} postow`);
    return posty;
  } catch (err) {
    if (err instanceof TypeError) {
      console.error("Blad sieci:", err.message);
    } else {
      console.error("Blad HTTP:", err.message);
    }
    return [];
  }
}

