async function pobierzBezpiecznie(id) {
  const odpowiedz = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`);
  if (!odpowiedz.ok) {
    throw new Error(`HTTP ${odpowiedz.status}`);
  }
  return odpowiedz.json();
}

async function test() {
  try {
    await pobierzBezpiecznie(99999999);
  } catch (err) {
    console.log(err.message); // "HTTP 404"
  }
}

test();

async function wczytajListe() {
  const odpowiedz = await fetch("https://jsonplaceholder.typicode.com/posts?_limit=5");
  if (!odpowiedz.ok) throw new Error(`HTTP ${odpowiedz.status}`);
  const posty = await odpowiedz.json();
  console.log(posty.length); // 5
  return posty;
}

async function bezpiecznePobranie(url) {
  try {
    const odpowiedz = await fetch(url);
    if (!odpowiedz.ok) throw new Error(`HTTP ${odpowiedz.status}`);
    return await odpowiedz.json();
  } catch (err) {
    if (err instanceof TypeError) {
      console.log("Blad sieci:", err.message);
    } else {
      console.log("Blad HTTP:", err.message);
    }
  }
}

// fetch(url) zwraca Promise, ktory rozwiazuje sie do obiektu Response -
// to jest 'surowa' odpowiedz (naglowki, status), NIE same dane. Odczyt
// body odpowiedzi (np. jako JSON) to OSOBNA, rowniez asynchroniczna
// operacja - response.json() SAMA zwraca kolejny Promise, ktory
// rozwiazuje sie dopiero po sparsowaniu tresci. Dlatego potrzebne sa
// dwa oddzielne await: jeden na samo polaczenie/odpowiedz, drugi na
// faktyczne 'rozpakowanie' jej zawartosci.
